const violationsByIDs = `-- name: ViolationsByIDs :many
SELECT id, store_id, account_id, category, severity, escalated_from, status, origin_measure_id, created_by_admin_id, created_at, updated_at, revoked_reason, revoked_by_admin_id, revoked_at
FROM seller.violations
WHERE id = ANY($1::uuid[])
ORDER BY id
`

func (q *Queries) ViolationsByIDs(ctx context.Context, ids []uuid.UUID) ([]SellerViolation, error) {
	rows, err := q.db.Query(ctx, violationsByIDs, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SellerViolation{}
	for rows.Next() {
		var i SellerViolation
		if err := rows.Scan(
			&i.ID,
			&i.StoreID,
			&i.AccountID,
			&i.Category,
			&i.Severity,
			&i.EscalatedFrom,
			&i.Status,
			&i.OriginMeasureID,
			&i.CreatedByAdminID,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.RevokedReason,
			&i.RevokedByAdminID,
			&i.RevokedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
